/* ============================================
   ENTITY CARD COMPONENT
   Compact card with a centred icon or image
   and a label. Used on Icons and Logos pages.
   ============================================ */

.ds-entity-card {
  /* Layout */
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--gap-400);

  /* Sizing */
  flex: 1 1 0;
  min-width: 100px;

  /* Appearance */
  background: var(--color-bg-container-primary);
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-600);
  padding: var(--padding-500);
}

/* ============================================
   PREVIEW AREA
   ============================================ */

.ds-entity-card__preview {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  min-height: 48px;
}

/* ============================================
   ICON (Material Symbols Rounded)
   ============================================ */

.ds-entity-card__icon {
  --icon-size: var(--icon-size-800);
  color: var(--color-text-primary);
}

/* ============================================
   IMAGE (Logo SVGs etc.)
   ============================================ */

.ds-entity-card__image {
  max-width: 100%;
  max-height: 48px;
  object-fit: contain;
}

/* ============================================
   LABEL
   ============================================ */

.ds-entity-card__label {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
  text-align: center;
  word-break: break-word;
}

import type React from 'react';
import './EntityCard.css';

export interface EntityCardProps {
  /** Display label beneath the icon / image */
  label: string;
  /** Icon — Material Symbol name (string, e.g. "home") rendered via the rounded font, or custom element (ReactNode) */
  icon?: string | React.ReactNode;
  /** Path to an image asset — used instead of icon when provided */
  imageSrc?: string;
  /** Alt text for the image */
  imageAlt?: string;
  /** Additional CSS classes */
  className?: string;
}

/**
 * EntityCard
 * A compact card with a centred icon (Material Symbols Rounded)
 * or image and a label underneath. Used on Icons and Logos pages.
 */
export const EntityCard = ({
  label,
  icon,
  imageSrc,
  imageAlt,
  className = '',
}: EntityCardProps) => {
  const baseClass = 'ds-entity-card';
  const classes = [baseClass, className].filter(Boolean).join(' ');

  return (
    <div className={classes}>
      <div className={`${baseClass}__preview`}>
        {imageSrc ? (
          <img
            src={imageSrc}
            alt={imageAlt || label}
            className={`${baseClass}__image`}
          />
        ) : icon ? (
          typeof icon === 'string' ? (
            <span className={`${baseClass}__icon material-symbols-rounded`} aria-hidden="true">
              {icon}
            </span>
          ) : (
            <span className={`${baseClass}__icon`} aria-hidden="true">
              {icon}
            </span>
          )
        ) : null}
      </div>
      <span className={`${baseClass}__label`}>{label}</span>
    </div>
  );
};
